create type public.result_status as enum('pending_confirmation','finalized','disputed','voided');create type public.result_revision_status as enum('pending','accepted','superseded','rejected');create type public.ranked_effect_state as enum('active','suspended','none');
create table public.match_results(id uuid primary key default gen_random_uuid(),match_id uuid not null unique references public.matches,club_id uuid not null references public.clubs,event_id uuid not null references public.events,status public.result_status not null default 'pending_confirmation',current_revision_id uuid,version bigint not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.result_revisions(id uuid primary key default gen_random_uuid(),result_id uuid not null references public.match_results,match_id uuid not null references public.matches,revision_no int not null check(revision_no>0),score jsonb not null,score_digest text not null,winner_side smallint not null check(winner_side in(1,2)),status public.result_revision_status not null default 'pending',submitted_by uuid not null references public.players,submitted_at timestamptz not null default now(),supersedes_revision_id uuid references public.result_revisions,reason text,request_id uuid not null,unique(result_id,revision_no));
alter table public.match_results add constraint match_results_current_revision_fkey foreign key(current_revision_id) references public.result_revisions;
create unique index result_revision_request_idx on public.result_revisions(submitted_by,request_id);create index result_revisions_result_idx on public.result_revisions(result_id,revision_no desc);
create table public.result_confirmations(result_revision_id uuid not null references public.result_revisions,player_id uuid not null references public.players,side smallint not null check(side in(1,2)),score_digest text not null,confirmed_at timestamptz not null default now(),request_id uuid not null,primary key(result_revision_id,player_id),unique(player_id,request_id));
create table public.official_results(id uuid primary key default gen_random_uuid(),match_id uuid not null references public.matches,club_id uuid not null references public.clubs,authoritative_revision_id uuid not null unique references public.result_revisions,effect_state public.ranked_effect_state not null,finalized_at timestamptz not null default now(),finalized_by uuid not null references public.players,eligibility_evidence jsonb not null,calculation_version bigint,calculation_checksum text,updated_at timestamptz not null default now());create unique index official_results_one_match_idx on public.official_results(match_id);
create table private.rating_ledger(id bigint generated always as identity primary key,official_result_id uuid not null references public.official_results,club_id uuid not null references public.clubs,player_id uuid not null references public.players,rule_version text not null,pre_rating numeric(10,2) not null,expected numeric(12,10) not null,delta numeric(10,2) not null,post_rating numeric(10,2) not null,created_at timestamptz not null default now(),unique(official_result_id,player_id,rule_version));create unique index rating_ledger_result_player_idx on private.rating_ledger(official_result_id,player_id,rule_version);
create table private.calculation_events(id bigint generated always as identity primary key,official_result_id uuid not null references public.official_results,rule_version text not null,input_checksum text not null,output_checksum text not null,calculation_version bigint not null,created_at timestamptz not null default now(),unique(official_result_id,rule_version));
create table public.player_statistics(player_id uuid primary key references public.players,rating numeric(10,2) not null default 1500,wins int not null default 0,losses int not null default 0,current_streak int not null default 0,longest_win_streak int not null default 0,last_match_at timestamptz,calculation_version bigint not null default 0,updated_at timestamptz not null default now());
create table public.leaderboard_entries(id uuid primary key default gen_random_uuid(),scope text not null check(scope in('overall','club')),club_id uuid references public.clubs,player_id uuid not null references public.players,rating numeric(10,2) not null,wins int not null,losses int not null,win_rate numeric(8,6) not null,current_streak int not null,longest_win_streak int not null,last_match_at timestamptz,calculation_version bigint not null,unique nulls not distinct(scope,club_id,player_id),check((scope='overall' and club_id is null)or(scope='club' and club_id is not null)));
create sequence private.competition_calculation_version;
create index leaderboard_rank_idx on public.leaderboard_entries(scope,club_id,rating desc,wins desc,win_rate desc,losses,last_match_at desc,player_id);
alter table public.match_results enable row level security;alter table public.result_revisions enable row level security;alter table public.result_confirmations enable row level security;alter table public.official_results enable row level security;alter table public.player_statistics enable row level security;alter table public.leaderboard_entries enable row level security;
create policy result_participant_or_club_read on public.match_results for select to authenticated using(exists(select 1 from public.matches m where m.id=match_id and(private.has_club_role(m.club_id,array['owner','organizer','score_official','staff']::public.club_role[])or exists(select 1 from public.match_participants mp where mp.match_id=m.id and mp.player_id=public.current_player_id()))));
create policy revision_result_read on public.result_revisions for select to authenticated using(exists(select 1 from public.match_results r where r.id=result_id));create policy confirmation_result_read on public.result_confirmations for select to authenticated using(exists(select 1 from public.result_revisions rr join public.match_results r on r.id=rr.result_id where rr.id=result_revision_id));create policy official_authenticated_read on public.official_results for select to authenticated using(true);create policy statistics_read on public.player_statistics for select using(true);create policy leaderboard_read on public.leaderboard_entries for select using(true);
revoke all on public.match_results,public.result_revisions,public.result_confirmations,public.official_results,public.player_statistics,public.leaderboard_entries from anon,authenticated;grant select on public.match_results,public.result_revisions,public.result_confirmations,public.official_results,public.player_statistics,public.leaderboard_entries to authenticated;grant select on public.player_statistics,public.leaderboard_entries to anon;
